import { ConflictError, ValidationError } from "./errors";
import { TaskStatus } from "./task-status";

export interface NewTaskProps {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date;
  status?: TaskStatus;
}

export class Task {
  private _status: TaskStatus;
  private _assigneeId: string | undefined;

  private constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: string,
    readonly description: string,
    readonly dueDate: Date | undefined,
    status: TaskStatus,
  ) {
    this._status = status;
  }

  static create(props: NewTaskProps): Task {
    const title = props.title.trim();
    if (title === "") {
      throw new ValidationError("task title must not be empty");
    }
    if (props.dueDate !== undefined && Number.isNaN(props.dueDate.getTime())) {
      throw new ValidationError("due date is invalid");
    }
    return new Task(
      props.id,
      props.projectId,
      title,
      props.description,
      props.dueDate,
      props.status ?? "todo",
    );
  }

  get status(): TaskStatus {
    return this._status;
  }

  get assigneeId(): string | undefined {
    return this._assigneeId;
  }

  assignTo(userId: string): void {
    this._assigneeId = userId;
  }

  markDone(): void {
    if (this._status === "done") {
      throw new ConflictError("task is already done");
    }
    this._status = "done";
  }
}

